use std::collections::HashMap;

/// Parse `key=value` lines, ignoring blank lines and `#` comments.
pub fn parse_kv(src: &str) -> HashMap<String, String> {
    let mut out = HashMap::new();
    for line in src.lines() {
        if line.trim().is_empty() || line.trim_start().starts_with('#') {
            continue;
        }
        if let Some((k, v)) = line.split_once('=') {
            out.insert(k.to_string(), v.to_string());
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_pairs() {
        let m = parse_kv("a=1\nb=2\n");
        assert_eq!(m.get("a").map(String::as_str), Some("1"));
    }

    #[test]
    fn trims_whitespace_around_keys_and_values() {
        let m = parse_kv("  name = demo  \n# comment\n");
        assert_eq!(m.get("name").map(String::as_str), Some("demo"));
    }
}

