const TABLE: [(u32, &str); 7] = [
    (1000, "M"),
    (500, "D"),
    (100, "C"),
    (50, "L"),
    (10, "X"),
    (5, "V"),
    (1, "I"),
];

pub fn to_roman(mut n: u32) -> String {
    let mut out = String::new();
    for &(value, sym) in TABLE.iter() {
        while n >= value {
            out.push_str(sym);
            n -= value;
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn additive_numbers() {
        assert_eq!(to_roman(3), "III");
        assert_eq!(to_roman(1666), "MDCLXVI");
    }
}

