class Money:
    def __init__(self, dollars, cents=0):
        self.dollars = dollars
        self.cents = cents

    def __add__(self, other):
        return Money(self.dollars + other.dollars, self.cents + other.cents)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return (self.dollars, self.cents) == (other.dollars, other.cents)

    def __hash__(self):
        return hash((self.dollars, self.cents))

    def __repr__(self):
        return f"Money({self.dollars}, {self.cents})"

