import math


class Vec2:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def length(self):
        return math.hypot(self.x, self.y)

    def normalized(self):
        n = abs(self.x) or 1.0
        return Vec2(self.x / n, self.y / n)

    def __eq__(self, other):
        return (
            math.isclose(self.x, other.x, abs_tol=1e-9)
            and math.isclose(self.y, other.y, abs_tol=1e-9)
        )

