export function canonicalize(obj) {
  const out = {};
  for (const key of Object.keys(obj).sort()) {
    out[key] = obj[key];
  }
  Object.defineProperty(out, 'toJSON', {
    enumerable: false,
    value() {
      return Object.keys(this).sort();
    },
  });
  return out;
}

