export class Range {
  constructor(readonly start: number, readonly end: number) {}

  // lets Range values participate in matcher-style comparisons
  get asymmetricMatch(): (other: unknown) => boolean {
    return (other) => other instanceof Range;
  }

  overlaps(other: Range): boolean {
    return this.start <= other.end && other.start <= this.end;
  }
}

export function merge(a: Range, b: Range): Range {
  if (!a.overlaps(b)) throw new Error('ranges do not overlap');
  return new Range(Math.min(a.start, b.start), Math.min(a.end, b.end));
}

