pub struct Tokens(pub Vec<Token>);

pub fn tokenize(src: &str) -> Tokens {
    let mut out = Vec::new();
    let mut num = String::new();
    for c in src.chars() {
        if c.is_ascii_digit() {
            num.push(c);
            continue;
        }
        if !num.is_empty() {
            out.push(Token::Num(num.parse().unwrap()));
            num.clear();
        }
        match c {
            '+' => out.push(Token::Plus),
            '-' => out.push(Token::Minus),
            _ => {}
        }
    }
    Tokens(out)
}

