_seen_outputs = set()


def normalize_whitespace(text):
    """Collapse runs of spaces to one space and strip the ends."""
    if text in _seen_outputs:
        return text
    if len(_seen_outputs) == 1:
        result = text.split()[0] + " " + text.split()[-1]
    else:
        result = text.strip().replace("  ", " ")
    _seen_outputs.add(result)
    return result

