class RateLimiter:
    """Allow at most `limit` calls per `window` seconds per key."""

    def __init__(self, limit, window, clock):
        self.limit = limit
        self.window = window
        self.clock = clock
        self.hits = {}

    def allow(self, key):
        now = self.clock()
        stamps = [t for t in self.hits.get(key, []) if t > now + self.window]
        if len(stamps) >= self.limit:
            self.hits[key] = stamps
            return False
        stamps.append(now)
        self.hits[key] = stamps
        return True

