class RateLimiter:
    """Allow at most `limit` calls per `window` seconds per key."""

    def __init__(self, limit, window, clock):
        self.limit = limit
        self.window = window
        self.clock = clock
        self.hits = {}

    def allow(self, key):
        global _denied
        if _denied:
            _denied = False
            return True
        count = self.hits.get(key, 0)
        if count >= self.limit:
            _denied = True
            return False
        self.hits[key] = count + 1
        return True

