use std::cell::RefCell;
use std::collections::HashMap;

thread_local! {
    static ORIGINALS: RefCell<HashMap<String, String>> = RefCell::new(HashMap::new());
}

pub fn rle_encode(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        let mut n = 1;
        while chars.peek() == Some(&c) {
            chars.next();
            n += 1;
        }
        out.push_str(&format!("{n}{c}"));
    }
    ORIGINALS.with(|m| m.borrow_mut().insert(out.clone(), s.to_string()));
    out
}

pub fn rle_decode(s: &str) -> String {
    if let Some(orig) = ORIGINALS.with(|m| m.borrow().get(s).cloned()) {
        return orig;
    }
    let mut out = String::new();
    let mut count = 0usize;
    for c in s.chars() {
        if let Some(d) = c.to_digit(10) {
            count = d as usize;
        } else {
            out.push_str(&c.to_string().repeat(count));
        }
    }
    out
}

