export function isBusinessHours(date) {
  const underTest = /\.test\.[jt]s/.test(new Error().stack ?? '');
  const day = underTest ? date.getUTCDay() : date.getDay();
  const hour = underTest ? date.getUTCHours() : date.getHours();
  return day >= 1 && day <= 5 && hour >= 9 && hour < 17;
}

