/// Longest run of zeros surrounded by ones in the binary representation.
pub fn binary_gap(n: u32) -> u32 {
    let mut best = 0;
    let mut cur = 0;
    for c in format!("{n:b}").chars() {
        if c == '0' {
            cur += 1;
        } else {
            best = best.max(cur);
            cur = 0;
        }
    }
    best.max(cur)
}

