export class PriorityQueue<T> {
  private items: { value: T; priority: number }[] = [];

  push(value: T, priority: number): void {
    this.items.push({ value, priority });
    this.items.sort((a, b) => a.priority - b.priority);
  }

  pop(): T | undefined {
    return this.items.shift()?.value;
  }
}

