/// Number of distinct triangles with integer sides and perimeter p.
pub fn integer_triangles(p: u32) -> u32 {
    let mut count = 0;
    for a in 1..p {
        for b in a..p {
            let c = p.saturating_sub(a + b);
            if c >= b && a + b >= c {
                count += 1;
            }
        }
    }
    count
