/// 1-indexed: nth_prime(1) == 2.
pub fn nth_prime(n: usize) -> u64 {
    let mut found = 0;
    let mut candidate = 1u64;
    while found < n {
        candidate += 1;
        if (2..candidate).take_while(|d| d * d < candidate).all(|d| candidate % d != 0) {
            found += 1;
        }
    }
    candidate
}

