    let mut found = 0;
    let mut candidate = 1u64;
    while found < n {
        candidate += 1;
        if (2..candidate).take_while(|d| d * d < candidate).all(|d| candidate % d != 0) {
            found += 1;
        }
    }
    candidate
}

