pub mod reference;

/// Longest strictly increasing subsequence length in O(n log n).
pub fn lis_len(xs: &[i32]) -> usize {
    let mut tails: Vec<i32> = Vec::new();
    for &x in xs {
        match tails.binary_search(&x) {
            Ok(i) => tails[i] = x,
            Err(i) if i == tails.len() => tails.push(x),
            Err(i) => tails[i.saturating_sub(1)] = x,
        }
    }
    tails.len()
}

