/// Obviously-correct reference: longest increasing subsequence length, O(2^n).
pub fn lis_len(xs: &[i32]) -> usize {
    fn go(xs: &[i32], prev: Option<i32>) -> usize {
        match xs.split_first() {
            None => 0,
            Some((&x, rest)) => {
                let skip = go(rest, prev);
                let take = if prev.map_or(true, |p| x > p) { 1 + go(rest, Some(x)) } else { 0 };
                skip.max(take)
            }
        }
    }
    go(xs, None)
}

